const wfail = (status, m) => [{ json: { ok: false, status, body: { success: false, message: m } } }];

const falta = ['ERPNEXT_DOMAIN', 'ERPNEXT_API_KEY', 'ERPNEXT_API_SECRET'].filter(k => !$env[k]);
if (falta.length) return wfail(500, 'PENDENTE_CONFIGURACAO_RITMO: variáveis ausentes: ' + falta.join(', '));
const b = $input.first().json.body || {};
const order_nsu = String(b.order_nsu || '').trim();
if (!/^[A-Za-z0-9._-]{1,100}$/.test(order_nsu)) return wfail(400, 'Pedido não encontrado');
const transaction_nsu = String(b.transaction_nsu || '').trim();
const slug = String(b.invoice_slug || b.slug || '').trim();
if (!transaction_nsu || !slug) return wfail(400, 'Webhook sem transaction_nsu/invoice_slug');
const paid = b.paid_amount ?? b.amount ?? null;
return [{ json: { ok: true, order_nsu, transaction_nsu, slug, valor_webhook: paid === null ? null : Number(paid) } }];

const wfail = (status, m) => [{ json: { ok: false, status, body: { success: false, message: m } } }];

const c = $input.first().json.data || {};
const bad = (m) => wfail(400, m);
if (c.status !== 'conectado') return bad('PENDENTE_CONFIGURACAO_INFINITEPAY: conta InfinitePay não está conectada (status: ' + (c.status || 'desconhecido') + ')');
let meta = {}; try { meta = JSON.parse(c.metadados || '{}'); } catch (e) {}
const handle = String(meta.handle || meta.infinite_tag || c.conta_conectada || '').trim().replace(/^[$@]/, '');
if (!/^[A-Za-z0-9._-]{2,64}$/.test(handle)) return bad('PENDENTE_CONFIGURACAO_INFINITEPAY: InfiniteTag (handle) não identificada na credencial (metadados.handle ou conta_conectada)');

const e = $('Valida webhook').first().json;
return [{ json: { ok: true, payload: { handle, order_nsu: e.order_nsu, transaction_nsu: e.transaction_nsu, slug: e.slug } } }];

const wfail = (status, m) => [{ json: { ok: false, status, body: { success: false, message: m } } }];

const j = $input.first().json;
const e = $('Valida webhook').first().json;
if (!(j.success === true && j.paid === true)) return wfail(400, 'Pagamento não confirmado pela InfinitePay');
const pago = j.paid_amount === undefined || j.paid_amount === null ? null : Number(j.paid_amount);
if (e.valor_webhook !== null && pago !== null && Number.isFinite(e.valor_webhook) && Math.round(e.valor_webhook) !== Math.round(pago)) return wfail(400, 'Valor do webhook diverge do valor confirmado pela InfinitePay');
// Confirmado pela própria InfinitePay. Este workflow não grava nada: reentregas repetem apenas a verificação (idempotente).
return [{ json: { status: 200, body: { success: true, message: null } } }];

const it = $input.first().json || {}; const e = it.error || it;
const up = Number(e.httpCode || e.statusCode || e.status || 0);
return [{ json: { status: 400, body: { success: false, message: 'Falha ao confirmar o pagamento na InfinitePay' + (up ? ' (HTTP ' + up + ')' : '') } } }];

const it = $input.first().json || {}; const e = it.error || it;
const up = Number(e.httpCode || e.statusCode || e.status || 0);
return [{ json: { status: 400, body: { success: false, message: up === 404 ? 'PENDENTE_CONFIGURACAO_INFINITEPAY: credencial não encontrada' : 'Falha ao ler a credencial InfinitePay no Ritmo' } } }];
